class Solution:
    def singleNonDuplicate(self, nums: list[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if mid % 2 == 1:
                mid -= 1                    # always look at the first slot of a pair
            if nums[mid] == nums[mid + 1]:  # pairs still aligned: single is to the right
                lo = mid + 2
            else:
                hi = mid
        return nums[lo]

